ALTER TABLE portal_users ADD COLUMN must_change_password INTEGER NOT NULL DEFAULT 0 CHECK(must_change_password IN (0,1));
ALTER TABLE symptom_checkins ADD COLUMN additional_symptoms TEXT NOT NULL DEFAULT '';
ALTER TABLE symptom_checkins ADD COLUMN review_status TEXT NOT NULL DEFAULT 'Pending Review';
ALTER TABLE patient_uploads ADD COLUMN sputum_entry_id INTEGER REFERENCES sputum_entries(id);
CREATE TABLE IF NOT EXISTS sputum_entries (id INTEGER PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), user_id INTEGER NOT NULL REFERENCES portal_users(id), observed_at TEXT NOT NULL, colour TEXT NOT NULL, amount TEXT NOT NULL, consistency TEXT NOT NULL, cough TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'Pending Review');
CREATE INDEX IF NOT EXISTS sputum_patient_time ON sputum_entries(patient_id,observed_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS sputum_entry_history (id INTEGER PRIMARY KEY, entry_id INTEGER NOT NULL REFERENCES sputum_entries(id), changed_at TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES portal_users(id), snapshot TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sputum_reviews (id INTEGER PRIMARY KEY, entry_id INTEGER NOT NULL REFERENCES sputum_entries(id), patient_id TEXT NOT NULL REFERENCES patients(patient_id), doctor_id INTEGER NOT NULL REFERENCES portal_users(id), notes TEXT NOT NULL, follow_up TEXT NOT NULL, shared INTEGER NOT NULL CHECK(shared IN (0,1)), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sputum_reviews_entry ON sputum_reviews(entry_id,id DESC);
CREATE TABLE IF NOT EXISTS care_plan_versions (id INTEGER PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), doctor_id INTEGER NOT NULL REFERENCES portal_users(id), created_at TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), title TEXT NOT NULL, start_date TEXT NOT NULL, review_date TEXT, food_guidance TEXT NOT NULL, breakfast TEXT NOT NULL, lunch TEXT NOT NULL, dinner TEXT NOT NULL, snacks TEXT NOT NULL, hydration_target_ml INTEGER CHECK(hydration_target_ml BETWEEN 1 AND 10000), hydration_instructions TEXT NOT NULL, activities TEXT NOT NULL, activity_schedule TEXT NOT NULL, activity_restrictions TEXT NOT NULL, notes TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS care_plans_patient ON care_plan_versions(patient_id,id DESC);
CREATE TABLE IF NOT EXISTS daily_care_logs (id INTEGER PRIMARY KEY, patient_id TEXT NOT NULL REFERENCES patients(patient_id), user_id INTEGER NOT NULL REFERENCES portal_users(id), kind TEXT NOT NULL CHECK(kind IN ('meal','hydration','activity')), occurred_at TEXT NOT NULL, created_at TEXT NOT NULL, item TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Completed','Not completed','Not applicable')), amount_ml INTEGER CHECK(amount_ml BETWEEN 1 AND 5000), duration_minutes INTEGER CHECK(duration_minutes BETWEEN 0 AND 1440), effort TEXT NOT NULL, comments TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'Pending Review', client_key TEXT NOT NULL, UNIQUE(user_id,client_key));
CREATE INDEX IF NOT EXISTS daily_care_patient_time ON daily_care_logs(patient_id,occurred_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS daily_care_reviews (id INTEGER PRIMARY KEY, log_id INTEGER NOT NULL REFERENCES daily_care_logs(id), doctor_id INTEGER NOT NULL REFERENCES portal_users(id), notes TEXT NOT NULL, shared INTEGER NOT NULL CHECK(shared IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS portal_audit (id INTEGER PRIMARY KEY, actor_id INTEGER NOT NULL REFERENCES portal_users(id), patient_id TEXT REFERENCES patients(patient_id), action TEXT NOT NULL, record_id INTEGER, created_at TEXT NOT NULL);
